//! Purpose:
//! PHP 8.5.8 `ext/dom` php-src tests for php-src's `modern/html/encoding` folder, as Elephc codegen tests.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/dom_php_src/mod.rs`.
//!
//! Key details:
//! - Each test keeps the php-src program and expected output verbatim; its doc
//!   comment names the PHPT it was migrated from.
//! - A test Elephc does not pass yet is `#[ignore]`d with the missing behaviour, and
//!   php-src's own environment skips keep their `SKIPIF` message.

use super::*;

/// php-src `ext/dom/tests/modern/html/encoding/HTMLDocument_GB18030.phpt`: Dom\HTMLDocument GB18030 encoding test
#[test]
#[ignore = r#"DOM port pending: Undefined class: Dom\HTMLDocument"#]
fn test_htmldocument_gb18030() {
    if skip_without_xml_native("test_htmldocument_gb18030") {
        return;
    }
    let out = run_case(r#"modern/html/encoding"#, &[], r#"<?php

$dom = Dom\HTMLDocument::createFromFile(__DIR__ . "/gb18030.html");
var_dump($dom->charset);
$dom->documentElement->firstChild->nextElementSibling->textContent = "é";
$output = $dom->saveHtml();
echo $output, "\n";
$dom->saveHtmlFile(__DIR__ . "/gb18030_output.tmp");
var_dump(file_get_contents(__DIR__ . "/gb18030_output.tmp") === $output);

echo "--- After changing encoding to UTF-8 ---\n";
$dom->charset = "UTF-8";
echo $dom->saveHtml(), "\n";

"#);
    assert_exact(&out, b"string(7) \x22gb18030\x22\x0a<!DOCTYPE html><html><head>\x0a<meta charset=\x22gb18030\x22>\x0a</head>\x0a<body>\xa8\xa6</body></html>\x0abool(true)\x0a--- After changing encoding to UTF-8 ---\x0a<!DOCTYPE html><html><head>\x0a<meta charset=\x22gb18030\x22>\x0a</head>\x0a<body>\xc3\xa9</body></html>");
}

