/// php-src `ext/dom/tests/modern/html/encoding/HTMLDocument_createFromFile_http_header.phpt`: Dom\HTMLDocument::createFromFile() HTTP header Content-Type
#[test]
#[ignore = r#"needs php-src's ext/standard/tests/http/server.inc test HTTP server"#]
fn test_htmldocument_create_from_file_http_header() {
    if skip_without_xml_native("test_htmldocument_create_from_file_http_header") {
        return;
    }
    let out = run_case(r#"modern/html/encoding"#, &[], r#"<?php
require "./ext/standard/tests/http/server.inc";

$tests = [
    "No slashes" => [
        "foo",
        "      ",
    ],
    "Invalid type/subtype" => [
        "/html; Charset=\"ISO-8859-1\"",
        "text/; Charset=\"ISO-8859-1\"",
        "tex°t/html; Charset=\"ISO-8859-1\"",
        "/; Charset=\"ISO-8859-1\"",
        "$/€; Charset=\"ISO-8859-1\"",
        "; Charset=\"ISO-8859-1\"",
        ";",
        "",
        "    \t",
    ],
    "Valid type/subtype without charset" => [
        "text/html; x=ISO-8859-1",
        "text/html; x=\"ISO-8859-1\"",
        "text/html; charet=\"ISO-8859-1\"",
        "text/html; chars et=\"ISO-8859-1\"",
    ],
    "All valid inputs" => [
        "text/html; charset=ISO-8859-1",
        "\t\r text/html; charset=ISO-8859-1   \t",
        "\t\r text/html; charset=ISO-8859-1   \t;bar=\"foo\"",
        "\t\r text/html; charset=ISO-8859-1   \t;bar=\"foo\"\r\n\t ",
        "text/html; foo=bar;charset=ISO-8859-1",
        "text/html; foo=bar;charset=ISO-8859-1;bar=\"foooooo\"",
        "text/html;;;; charset=ISO-8859-1",
        "text/html; Charset=\"ISO-8859-1\"",
        "text/html; Charset=\"ISO\\-8859-1\"",
        "text/html; ;;   ; ;; Charset=\"ISO-8859-1\"",
        "text/html;Charset=\"ISO-8859-1",
        "tex.t/h#\$%!&'*%2B-.^_`|~tml;Charset=\"ISO-8859-1\"", // Note: have to encode + as 2B because of implementation details of http_server()
    ],
    "Valid input, but invalid encoding name" => [
        "text/html;Charset=\"ISO-8859-1\\",
        "text/html;Charset=\"ISO-8859-1\\\"",
        "text/html;Charset=\"foobar\\\"",
        "text/html;Charset=\"%7F\\\"",
        "text/html;Charset=\"\\\"",
        "text/html;Charset=",
    ],
];

foreach ($tests as $name => $headers) {
    echo "--- $name ---\n";
    $responses = array_map(fn ($header) => "data://text/plain,HTTP/1.1 200 OK\r\nContent-Type: " . $header . "\r\n\r\n" . "<p>\xE4\xF6\xFC</p>\n", $headers);
    ['pid' => $pid, 'uri' => $uri] = http_server($responses);
    for ($i = 0; $i < count($responses); $i++) {
        $result = Dom\HTMLDocument::createFromFile($uri, LIBXML_NOERROR);
        echo $result->getElementsByTagName("p")[0]->textContent, "\n";
    }
    http_server_kill($pid);
}
"#);
    assert_exact(&out, r#"--- No slashes ---
���
���
--- Invalid type/subtype ---
���
���
���
���
���
���
���
���
���
--- Valid type/subtype without charset ---
���
���
���
���
--- All valid inputs ---
äöü
äöü
äöü
äöü
äöü
äöü
äöü
äöü
äöü
äöü
äöü
äöü
--- Valid input, but invalid encoding name ---
���
���
���
���
���
���"#);
}

/// php-src `ext/dom/tests/modern/html/encoding/HTMLDocument_createFromFile_override_encoding.phpt`: Dom\HTMLDocument::createFromFile() with overrideEncoding
#[test]
#[ignore = r#"DOM port pending: Undefined class: Dom\HTMLDocument"#]
fn test_htmldocument_create_from_file_override_encoding() {
    if skip_without_xml_native("test_htmldocument_create_from_file_override_encoding") {
        return;
    }
    let out = run_case(r#"modern/html/encoding"#, &[], r#"<?php

try {
    Dom\HTMLDocument::createFromFile(__DIR__ . '/gb18030_without_charset.html', overrideEncoding: 'nonexistent');
} catch (ValueError $e) {
    echo $e->getMessage(), "\n";
}

// The override encoding matches with the document encoding attribute
$dom = Dom\HTMLDocument::createFromFile(__DIR__ . '/gb18030_without_charset.html', overrideEncoding: 'GB18030');
var_dump($dom->documentElement->lastChild->textContent);
var_dump($dom->charset);

// The override encoding mismatches with the document encoding attribute
$dom = Dom\HTMLDocument::createFromFile(__DIR__ . '/fallback_encoding.html', overrideEncoding: 'Windows-1252');
var_dump($dom->documentElement->lastChild->textContent);
var_dump($dom->charset);

"#);
    assert_exact(&out, r#"Dom\HTMLDocument::createFromFile(): Argument #3 ($overrideEncoding) must be a valid document encoding
string(20) "
    Héllo, world!
"
string(7) "gb18030"
string(1) "
"
string(12) "windows-1252""#);
}

