/// php-src `ext/dom/tests/modern/html/encoding/HTMLDocument_encoding_edge_case_01.phpt`: Dom\HTMLDocument edge case encoding 01
#[test]
#[ignore = r#"DOM port pending: Undefined class: Dom\HTMLDocument"#]
fn test_htmldocument_encoding_edge_case_01() {
    if skip_without_xml_native("test_htmldocument_encoding_edge_case_01") {
        return;
    }
    let out = run_case(r#"modern/html/encoding"#, &[], r#"<?php

// UTF-8 -> UTF-8
// Create a UTF-8 string where a UTF-8 byte sequence falls over the boundary of the 4096 byte buffer
$dom = Dom\HTMLDocument::createEmpty();
$element = $dom->createElement("container");
$dom->append($element);
$element->append(str_repeat("A", 4096 - 2 - strlen("<container>")) . "\xf0\x90\x8d\x88AA");
var_dump($dom->saveHtml());

"#);
    assert_exact(&out, r#"string(4112) "<container>𐍈AA</container>""#);
}

/// php-src `ext/dom/tests/modern/html/encoding/HTMLDocument_encoding_edge_case_02.phpt`: Dom\HTMLDocument edge case encoding 02
#[test]
#[ignore = r#"DOM port pending: Undefined class: Dom\HTMLDocument"#]
fn test_htmldocument_encoding_edge_case_02() {
    if skip_without_xml_native("test_htmldocument_encoding_edge_case_02") {
        return;
    }
    let out = run_case(r#"modern/html/encoding"#, &[], r#"<?php

// UTF-8 -> GB18030
$dom = Dom\HTMLDocument::createEmpty("GB18030");
$element = $dom->createElement("container");
$dom->append($element);
// Create a UTF-8 string where a UTF-8 byte sequence falls over the boundary of the 4096 byte buffer
// *and* the sequence also falls over the boundary for the result
$element->append(str_repeat("A", 4096 - 2 - strlen("<container>")) . "\xf0\x90\x8d\x88AA");
var_dump($output = $dom->saveHtml());

// GB18030 encoding of the above UTF-8 symbol
var_dump($output[4094] == "\x90");
var_dump($output[4095] == "\x30");
var_dump($output[4096] == "\xd5");
var_dump($output[4097] == "\x30");

"#);
    assert_exact(&out, b"string(4112) \x22<container>\x900\xd50AA</container>\x22\x0abool(true)\x0abool(true)\x0abool(true)\x0abool(true)");
}

/// php-src `ext/dom/tests/modern/html/encoding/HTMLDocument_encoding_edge_case_03.phpt`: Dom\HTMLDocument edge case encoding 03
