/// php-src `ext/dom/tests/modern/html/encoding/HTMLDocument_encoding_edge_case_05.phpt`: Dom\HTMLDocument edge case encoding 05
#[test]
#[ignore = r#"DOM port pending: Undefined class: Dom\HTMLDocument"#]
fn test_htmldocument_encoding_edge_case_05() {
    if skip_without_xml_native("test_htmldocument_encoding_edge_case_05") {
        return;
    }
    let out = run_case(r#"modern/html/encoding"#, &[], r#"<?php

// GB18030 -> UTF-8
$header = "<!doctype html><html><head><meta charset=\"gb18030\"></head><body>";
$padding_required_until_4094 = 4094 - strlen($header);
$trailer = "\x90\x30\xd5\x30";
$dom = Dom\HTMLDocument::createFromString($header . str_repeat("A", $padding_required_until_4094) . $trailer);
// GB18030 byte sequence crossing the 4096 boundary
var_dump($dom->charset);
$dom->charset = "UTF-8";
var_dump($dom->saveHtml());

"#);
    assert_exact(&out, r#"string(7) "gb18030"
string(4112) "<!DOCTYPE html><html><head><meta charset="gb18030"></head><body>𐍈</body></html>""#);
}

